def quoted(p,line):
    # A few authored locator lines are blank separators; quote the immediately
    # following nonblank line, within the same already-read passage.
    k=int(line)-1
    while not texts[p][k].strip(): k+=1
    s=texts[p][k].strip()
    return s if len(s)<=230 else s[:227]+'...'

def item(i,sources,kind,cote,scans,lines,statement,reason,check='agrees',reconstruction='',q=None,path=P93):
    d=dict(id=f'SA04-{i}',sources=sources,kind=kind,cote=str(cote),scans=scans,lines=f'{path}: {lines}',his_words=quoted(path,q or lines.split('-')[0]),statement=statement,reconstruction=reconstruction or 'Only the explicit modern qualification stated in this entry is supplied by this audit; no missing manuscript proof is silently restored.',check=check,check_reason=reason)
    items.append(d)
    events.append([d['id'],DAY,WHO,'used and rechecked in this run','Textual comparison of the complete note with the cited transcription passage; this event is not a proof certification. '+reason])
    return d

