def claim(n,ids,status,klass,group,refs,calc,fate,present,statement=None,confidence='high'):
    ids=[nested[z] if not z.isdigit() else int(z) for z in ids.split(',')]
    ds=[byitem[f'SA04-{i}'] for i in ids]
    cid=f'C-SA04-{n}'
    comp=('No numerical computation is required. The cited textual/proof analysis distinguishes a manuscript argument from a reconstruction.' if calc=='none' else f'programs/c_computations.py; outputs/c_computations.txt; labels {calc}. These are exact symbolic identities or finite counterexamples, not proof by sampling. See analysis.md for the universal argument.')
    d=dict(id=cid,items=[a['id'] for a in ds],cote=';'.join(dict.fromkeys(a['cote'] for a in ds)),scans='; '.join(dict.fromkeys(a['scans'] for a in ds)),lines='; '.join(dict.fromkeys(a['lines'] for a in ds)),his_statement=('Serre, printed offprint/course report: ' if 424<=n<=449 and n!=431 else 'Manuscript or reused typescript, as attributed in the item: ')+ds[0]['his_words'],statement=statement or ' '.join(a['statement'] for a in ds),status_on_pages=status,computation=comp,**{'class':klass},fate=fate,fate_date='Publication/circulation dates and exact locators are specified in fate and references.bib; no manuscript priority date inferred.',present_status='As of November 2026: '+present,refs=[] if refs=='none' else refs.split(','),confidence=confidence)
    claims.append(d);claim_search[cid]=group
    events.append([cid,DAY,WHO,'used and rechecked in this run','Read the cited source passage, compared exact hypotheses with the opened references, and recorded search group '+group+'. This event alone does not certify a complete proof.'])
    if calc!='none': events.append([cid,DAY,WHO,'computation or formal certificate','Reran saved program and output labels '+calc+'. Scope of finite checks is explicit in the computation field.'])

