byclaim={a['id']:a for a in claims}
def problem(n,title,cnums,as_he,plausible,state,why,worth,refs):
    cs=[byclaim[f'C-SA04-{int(z)}'] for z in cnums.split(',')]
    problems.append(dict(id=f'MP-SA04-{n}',title=title,occurrences=[dict(claim=c['id'],items=c['items'],cote=c['cote'],scans=c['scans'],lines=c['lines']) for c in cs],as_he_states=as_he,plausible_today=plausible,state_of_art='As of November 2026: '+state,why_open=why,worth=worth,refs=refs.split(',')))

